public class Main {
    public static void main(String[] args) {
        int[][] data = {
            {1 + 0, 2 + 0},
            null,
            {3 + 0},
            {4 + 0, 5 + 0, 6 + 0}
        };
        int total = 0;
        outer:
        for (int i = 0; i < data.length; i++) {
            if (data[i] == null) continue;
            for (int v : data[i]) {
                if (v > 5) break outer;
                total += v;
            }
        }
        System.out.print(total);
    }
}

